mapper.sql:
WHERE i.company_id = #{companyId}

	AND i.item_name LIKE CONCAT('%', #{itemName}, '%')


	AND i.item_bn LIKE CONCAT('%', #{itemBn}, '%')


	AND (rel.goods_bn LIKE CONCAT('%', #{goodsBn}, '%') OR i.goods_bn LIKE CONCAT('%', #{goodsBn}, '%'))


	AND rel.design_id = #{designId}


	AND w.design_name LIKE CONCAT('%', #{designName}, '%')


	AND i.approve_status = #{approveStatus[0]}


	AND i.approve_status IN

		#{st}



	AND i.item_category = #{itemCategory[0]}


	AND i.item_category IN

		#{cat}

mapper.select:
SELECT i.item_id AS item_id, i.item_name AS item_name, i.item_bn AS item_bn, i.goods_bn AS item_goods_bn, i.approve_status AS approve_status, i.item_category AS item_category, i.store AS store, i.price AS price, i.market_price AS market_price, i.pics AS pics, i.created AS created, i.updated AS updated, rel.design_id AS design_id, rel.goods_bn AS rel_goods_bn, w.design_name AS design_name, w.cover_pic AS cover_pic, rel.id AS rel_id, rel.created AS bind_created
ORDER BY rel.created DESC
LIMIT #{limit} OFFSET #{offset}

SELECT irt.item_id AS item_id, it.tag_id AS tag_id, it.tag_name AS tag_name,
	it.tag_color AS tag_color, it.font_color AS font_color
FROM items_rel_tags irt
INNER JOIN items_tags it ON irt.tag_id = it.tag_id
WHERE irt.company_id = #{companyId}
AND it.company_id = #{companyId}
AND irt.item_id IN

	#{id}
